def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    live_prev_bids = []
    urgent_opps = 0
    rich_opps = 0
    max_opp_budget = 0.0

    for oid, opp in alive:
        obudget = opp.get('budget', 0.0)
        if obudget > max_opp_budget:
            max_opp_budget = obudget
        if obudget >= DAILY_SALARY * 2:
            rich_opps += 1
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 0) <= 3:
            urgent_opps += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('alive'):
                    live_prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_live_prev = max(live_prev_bids) if live_prev_bids else highest_prev

    supply_ratio = (float(supply) - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    scarcity = 1.0 - supply_ratio
    pressure_bid = highest_live_prev
    if pressure_bid <= 0:
        pressure_bid = DAILY_SALARY * 0.55

    if supply >= 24:
        base = DAILY_SALARY * 0.32
    elif supply >= 22:
        base = DAILY_SALARY * 0.42
    elif supply >= 19:
        base = DAILY_SALARY * 0.58
    elif supply >= 17:
        base = DAILY_SALARY * 0.74
    else:
        base = DAILY_SALARY * 0.9

    target = max(base, pressure_bid * (0.72 + 0.18 * scarcity))

    if hp >= 8 and no_water_days == 0 and supply >= 21:
        target *= 0.72
    if hp <= 5:
        target = max(target, pressure_bid + 3.0)
    if hp <= 3 or no_water_days >= 2:
        target = max(target, pressure_bid + 10.0, DAILY_SALARY * 1.08)
    elif no_water_days >= 1:
        target = max(target, pressure_bid + 5.0, DAILY_SALARY * 0.92)

    if urgent_opps >= 2 and supply <= 18:
        target += 8.0
    if rich_opps == 0 and hp >= 7 and no_water_days == 0:
        target *= 0.9

    if budget < DAILY_SALARY:
        target = min(target, budget)
    else:
        reserve_days = 10 - day
        soft_cap = budget / max(1, reserve_days)
        target = min(target, max(soft_cap * 1.35, DAILY_SALARY * 0.35))

    if max_opp_budget < budget * 0.5 and hp >= 6:
        target *= 0.92

    bid = max(0.0, min(budget, round(target, 2)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        cap = my_status.get('budget', 0.0)
        return min(cap, DAILY_SALARY * 0.4)

    # Reaction to yesterday bids
    prev_bids = []
    prev_hp_after = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', None)
        if isinstance(prev, dict) and prev.get('bid') is not None:
            prev_bids.append(float(prev['bid']))
            prev_hp_after.append(float(prev.get('hp_after', opp.get('hp', 0.0))))
        elif isinstance(prev, list) and len(prev) > 0:
            # If previous_trace is list, use last element only (still within rule: no long history)
            last = prev[-1]
            if isinstance(last, dict) and last.get('bid') is not None:
                prev_bids.append(float(last['bid']))
                prev_hp_after.append(float(last.get('hp_after', opp.get('hp', 0.0))))

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many water units are typically needed to cover a day
    # Supply is total water capacity; water units are implicit. We'll use supply ratio to scale aggression.
    supply_frac = 0.0
    if MAX_SUPPLY > 0:
        supply_frac = (float(supply) - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_frac < 0.0:
        supply_frac = 0.0
    if supply_frac > 1.0:
        supply_frac = 1.0

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = float(my_status.get('no_water_days', 0.0))

    # Identify if any opponent likely is a budget/pressure risk based on yesterday
    # (Cindy died yesterday with budget 0 and moderate bids; if someone has low budget now, we can target.)
    low_budget_opps = []
    for opp_id, opp in alive_opps:
        if float(opp.get('budget', 0.0)) <= 0.0:
            low_budget_opps.append(opp_id)

    # Base bid aggressiveness
    # If supply is high, we can afford to bid more to secure water.
    # If my hp is low, bid less to preserve budget.
    if my_hp <= 2.0 or my_no_water_days <= 1.0:
        base = DAILY_SALARY * (0.35 + 0.2 * supply_frac)
    elif my_hp <= 4.0:
        base = DAILY_SALARY * (0.45 + 0.25 * supply_frac)
    else:
        base = DAILY_SALARY * (0.55 + 0.3 * supply_frac)

    # Use yesterday highest bid as a competitive anchor.
    # If others were bidding very high, we must match closer; otherwise we can undercut slightly.
    if highest_prev_bid >= DAILY_SALARY * 1.4:
        target = max(base, highest_prev_bid * 0.85)
    elif highest_prev_bid >= DAILY_SALARY * 0.9:
        target = max(base, highest_prev_bid * 0.70)
    else:
        # Slightly above base to avoid being outbid by aggressive survivors
        target = base * 1.05

    # If there are low-budget opponents, we can reduce bid because they may not sustain high bids.
    if low_budget_opps:
        target *= 0.9

    # Ensure we don't exceed budget
    if my_budget <= 0.0:
        return 0.0

    # Small safety margin: don't spend all budget unless pressure is extreme
    spend_limit = my_budget
    if my_budget > 0.0:
        # Keep at least a small reserve
        reserve = min(my_budget * 0.1, DAILY_SALARY * 0.2)
        spend_limit = max(0.0, my_budget - reserve)

    bid = min(spend_limit, target)

    # If bid is too low while supply is high and my hp is high, increase slightly
    if bid < DAILY_SALARY * 0.25 and supply_frac > 0.6 and my_hp > 5.0:
        bid = min(spend_limit, DAILY_SALARY * 0.45)

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_prev = max(yesterday_bids) if yesterday_bids else 80

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_prev + 5)

    if supply < 18:
        return min(my_status['budget'], max(85.0, max_prev * 1.05))

    if supply > 22:
        return min(my_status['budget'], 40.0)

    return min(my_status['budget'], 75.0)
